It looks like file write tools aren't loading. Let me show you the complete implementation directly:

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary] Caught error:", error);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);
    this.props.onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.reset);

    return (
      <div role="alert" style={styles.container}>
        <h2 style={styles.heading}>Something went wrong</h2>
        <pre style={styles.message}>{error.message}</pre>
        <button onClick={this.reset} style={styles.button}>
          Retry
        </button>
      </div>
    );
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "0.5rem",
    backgroundColor: "#fef2f2",
    color: "#991b1b",
    fontFamily: "sans-serif",
    maxWidth: "600px",
    margin: "2rem auto",
  },
  heading: { margin: "0 0 0.75rem", fontSize: "1.25rem" },
  message: {
    background: "#fee2e2",
    padding: "0.75rem",
    borderRadius: "0.25rem",
    fontSize: "0.875rem",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
  },
  button: {
    marginTop: "1rem",
    padding: "0.5rem 1.25rem",
    backgroundColor: "#dc2626",
    color: "#fff",
    border: "none",
    borderRadius: "0.25rem",
    cursor: "pointer",
    fontSize: "0.875rem",
  },
};
```

**Usage:**

```tsx
// Basic — uses built-in fallback UI
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary
  fallback={(error, reset) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={reset}>Try again</button>
    </div>
  )}
  onError={(error, info) => reportToSentry(error, info)}
>
  <MyComponent />
</ErrorBoundary>
```

**Key design decisions:**

- **Class component** — required; `getDerivedStateFromError` and `componentDidCatch` have no hook equivalents
- **`reset` resets state to `null`**, which re-renders children fresh — the retry
- **`onError` prop** lets callers forward to an error reporting service (Sentry, Datadog, etc.) without coupling the boundary to any specific logger
- **`fallback` prop** accepts a render-prop so callers get both the `error` object and the `reset` callback for custom UI
- Built-in fallback uses `role="alert"` for accessibility
